import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.CDU0sSpB.js";const _=JSON.parse('{"title":"运行环境与安全","description":"Hearth 如何用工作区、隔离、网络、凭据和隐私边界限制真实世界的影响。","frontmatter":{"title":"运行环境与安全","description":"Hearth 如何用工作区、隔离、网络、凭据和隐私边界限制真实世界的影响。","outline":false},"headers":[],"relativePath":"design/safety.md","filePath":"design/safety.md","lastUpdated":1793863446000}'),s={name:"design/safety.md"};function o(i,t,n,p,l,h){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="运行环境与安全" tabindex="-1">运行环境与安全 <a class="header-anchor" href="#运行环境与安全" aria-label="Permalink to &quot;运行环境与安全&quot;">​</a></h1><p class="lead">安全不是最后加上的一层防护，而是产品能否替用户接触真实文件、账号和设备的前提。Hearth 默认只给完成任务所需的最小范围，并在任务结束后收回临时能力。</p><h2 id="设计目标" tabindex="-1">设计目标 <a class="header-anchor" href="#设计目标" aria-label="Permalink to &quot;设计目标&quot;">​</a></h2><p>执行环境要清楚区分可读、可写、可联网和可使用凭据的范围。研究任务可以只读，代码和文档任务使用可回滚的工作区，不可信文件进入隔离环境，需要特定设备的任务只在那台设备执行。临时权限、文件挂载和网络规则不能无限期保留。</p><p>网络默认拒绝，只有任务明确需要的域名和端口才开放。系统通过代理记录访问，阻断本地管理接口和云环境元数据地址；下载内容先进入隔离区，经过扫描和解析后才能使用。绕过网络限制的尝试应被当作安全事件，而不是普通失败。</p><p>凭据由独立边界管理。模型和执行器看不到长期密码、刷新令牌和完整密钥，只能获得任务需要、短时间有效的能力；连接器在真正调用外部服务时注入凭据，使用过程要审计、脱敏并可以随时撤销。</p><p>本地优先是隐私设计的一部分。个人文件、记忆、事件和凭据默认保存在用户控制的环境中；使用远程模型、远程执行环境或云同步时，要明确哪些数据会离开设备、保留多久、能否删除和如何导出。</p><h2 id="设计取舍" tabindex="-1">设计取舍 <a class="header-anchor" href="#设计取舍" aria-label="Permalink to &quot;设计取舍&quot;">​</a></h2><p>工作区按任务风险选择，而不是所有任务共用一个大目录。只读工作区用于研究和审查；一次性工作区结束即销毁；写时复制工作区保留原件并支持差异和回滚；长期项目工作区有版本、配额和清理规则；远程设备工作区通过加密传输和短期授权访问。</p><table tabindex="0"><thead><tr><th>隔离方式</th><th>适用场景</th><th>局限</th></tr></thead><tbody><tr><td>受限进程</td><td>可信脚本和轻量工具</td><td>对恶意代码不是强边界</td></tr><tr><td>容器</td><td>一般代码、测试和文档转换</td><td>共享内核，不能把容器当成绝对安全</td></tr><tr><td>轻量虚拟机</td><td>不可信代码、外部文件和高风险研究</td><td>启动和资源成本更高</td></tr><tr><td>虚拟桌面</td><td>图形界面软件和不可信桌面应用</td><td>运维复杂，仍需网络与凭据控制</td></tr><tr><td>远程设备</td><td>必须在特定设备完成的操作</td><td>设备丢失、离线和撤销必须单独处理</td></tr></tbody></table><p>容器适合运营隔离，却不是对恶意代码的绝对保证。宏、下载文件、浏览器页面、外部代码和高风险文档应使用更强隔离。安全等级由任务来源、数据敏感度、动作可逆性和外部影响共同决定，不能只看执行器类型。</p><p>凭据不进入模型上下文。系统按账户、资源、动作、设备和时间发放短期能力，任务结束立即回收；日志、错误信息和模型输入自动脱敏。用户要能查看哪些连接仍然有效，并一键撤销全部授权。</p><p>供应链和设备安全同样属于产品边界。依赖要锁定版本、审计来源并保持最小化；扩展不能默认获得全部权限；设备配对要有身份和能力目录，设备丢失后可以撤销能力、轮换密钥并清理本地数据。发生严重异常时要有全局暂停和隔离入口，而不是只能逐条取消任务。</p>',13)])])}const f=a(s,[["render",o]]);export{_ as __pageData,f as default};
